/* Freedom Institute - history data. Every entry carries its source. */
window.FI_HISTORY=[{"years": "1945–1960", "title": "The Cold War was fought over the radio dial before it was fought anywhere else.", "framing": "The post-war settlement wrote freedom of information into international law and then spent a decade contradicting it. Occupying armies censored defeated countries, new republics wrote emergency powers into their constitutions, and the Soviet bloc built a jamming apparatus larger than the broadcasting it was designed to defeat. By 1960 the basic architecture of the century was set: a universal right on paper, and a transmitter war underneath it.", "events": [{"year": "September 1945 (censorship apparatus operated October 1945 – November 1949)", "place": "Japan (Allied Occupation)", "h": "MacArthur's occupation imposes a press code on defeated Japan", "body": "The Civil Censorship Detachment operated from October 1945 to November 1949, censoring mail, telephone, telegraph, film, radio and publications; publishers had to submit two copies of every proposed publication for review before it appeared.", "why": "It established that a democratising power would run pre-publication censorship as a tool of democratisation itself; an argument every later government has borrowed when censoring in the name of stability.", "srcTitle": "Civil Censorship Detachment, University of Maryland Libraries, Gordon W. Prange Collection", "srcUrl": "https://www.lib.umd.edu/prange/about-us/civil-censorship-detachment", "key": false, "sum": "Within roughly three weeks of arriving on 30 August 1945, MacArthur's GHQ issued a ten-point Press Code for Japanese news media."}, {"year": "October–November 1947", "place": "United States", "h": "Hollywood Ten cited for contempt; studios announce the blacklist", "body": "In November 1947 film executives issued the Waldorf Statement, pledging not to employ them unless they were acquitted or swore under oath they were not communists. One scholarly estimate, by Yale's Ralph Brown, puts the number who lost jobs across the McCarthy era at roughly 10,000, a figure that is an estimate rather than a count.", "why": "It showed that in an open society the effective censor need not be the state; a legislature can supply the names and private employers can supply the punishment.", "srcTitle": "Blacklists, The First Amendment Encyclopedia, Middle Tennessee State University", "srcUrl": "https://firstamendment.mtsu.edu/article/blacklists/", "key": false, "sum": "Ten screenwriters and directors refused to answer House Un-American Activities Committee questions about Communist Party membership and were cited for contempt of Congress in 1947; after appeals failed they went to prison in 1950."}, {"year": "10 December 1948", "place": "Paris (UN General Assembly)", "h": "The UN adopts Article 19, the right to seek and receive information", "body": "Article 19 protects not only expression but the freedom to \"seek, receive and impart information and ideas through any media and regardless of frontiers\", language deliberately drafted to cross borders. It was a declaration, not a treaty, and carried no enforcement machinery.", "why": "The \"regardless of frontiers\" clause turned cross-border broadcasting and, decades later, the open internet into a claimed legal right rather than a mere technical fact.", "srcTitle": "History of the Declaration, United Nations", "srcUrl": "https://www.un.org/en/about-us/udhr/history-of-the-declaration", "key": true, "sum": "The General Assembly adopted the Universal Declaration of Human Rights as Resolution 217 A (III) with eight abstentions and no votes against."}, {"year": "24 April 1949", "place": "Soviet Union", "h": "Moscow begins systematically jamming Voice of America broadcasts", "body": "Cold War Radio Museum records the Soviet bloc eventually operating 37 500-kilowatt shortwave transmitters against America's six, and spending more on blocking Western broadcasts than the entire worldwide budget of VOA. Soviet jamming did not stop until 30 November 1988.", "why": "Jamming was the first industrial-scale attempt to filter a communications medium at national borders, and it established the pattern, enormously expensive, never fully effective, that internet filtering repeats today.", "srcTitle": "Voice of America, The First Amendment Encyclopedia, Middle Tennessee State University", "srcUrl": "https://firstamendment.mtsu.edu/article/voice-of-america/", "key": true, "sum": "The United States had begun Russian-language broadcasting on 17 February 1947; on 24 April 1949 the USSR started deliberate jamming, and according to the First Amendment Encyclopedia soon had more than 1,000 transmitters directed at incoming signals."}, {"year": "26 June 1950 (judgment); First Amendment enacted 1951", "place": "India", "h": "India's court frees a banned magazine; Parliament rewrites the constitution", "body": "The government's response was the First Amendment to the Constitution in 1951, which added \"public order\" to the permissible restrictions on speech in Article 19(2). Whether Nehru's amendment was a pragmatic response to communal violence or a foundational narrowing of Indian free speech remains actively contested among Indian constitutional scholars.", "why": "It set the template by which democracies answer adverse free-speech rulings, not by defying the court, but by amending the text the court applied.", "srcTitle": "Romesh Thappar v. State of Madras, Columbia Global Freedom of Expression", "srcUrl": "https://globalfreedomofexpression.columbia.edu/cases/thappar-v-madras/", "key": true, "sum": "In Romesh Thappar v State of Madras, decided 26 May 1950, the Supreme Court struck down a ban on the leftist journal Cross Roads imposed under the Madras Maintenance of Public Order Act 1949, holding that \"public safety\" and \"public order\" were far broader grounds than the Constitution allowed."}, {"year": "4 July 1950", "place": "Lampertheim, West Germany → Czechoslovakia", "h": "Radio Free Europe's first broadcast goes out from a flatbed truck", "body": "Regular broadcasting from Munich began on 1 May 1951 under Ferdinand Peroutka, the service's first director. The station was covertly funded by the CIA, a fact not publicly acknowledged until the early 1970s.", "why": "It created the surrogate domestic broadcaster, a station that speaks to a closed country as though it were that country's own press, a model still in use from Radio Farda to Radio Free Asia.", "srcTitle": "The First Broadcasts of Radio Free Europe's Czechoslovak Service, RFE/RL", "srcUrl": "https://about.rferl.org/article/the-first-broadcasts-of-radio-free-europes-czechoslovak-service/", "key": false, "sum": "RFE's Czechoslovak Service opened with a 30-minute announcement in Czech and Slovak, transmitted through a 7.5-kilowatt transmitter mounted on a flatbed truck at Lampertheim, north of Mannheim."}, {"year": "1950 (Act No. 44 of 1950)", "place": "South Africa", "h": "Apartheid's Suppression of Communism Act creates the power to ban publications", "body": "South African History Online records that the Act \"severely limited what the media could report through banning threats and the silencing of individuals and organisations,\" and that it was amended in 1951 to reach people who had been communists at any earlier point in their lives.", "why": "It built the legal machine, banning orders against people and titles rather than prosecutions for specific articles, that South Africa used against the press for the next forty years.", "srcTitle": "Suppression of Communism Act 44 of 1950 severely limits what the media could report, South African History Online", "srcUrl": "https://sahistory.org.za/dated-event/suppression-communism-act-44-1950-severely-limits-what-media-could-report", "key": false, "sum": "The Suppression of Communism Act 44 of 1950 gave the state power to ban organisations, silence named individuals and prohibit publications, with a definition of \"communism\" broad enough to cover most opposition activity."}, {"year": "23 October – 4 November 1956", "place": "Hungary", "h": "Radio Free Europe is accused of encouraging a doomed uprising", "body": "The account is genuinely contested: a CIA review concluded RFE \"neither incited the Hungarian people to revolution nor promised outside military intervention,\" while an internal December 1956 review rated only 171 of 308 Hungarian-language programmes excellent or good, and investigators identified a single 4 November press review that suggested Western military help might be forthcoming. Historians including Charles Gati have argued RFE should have backed Imre Nagy's reformist alternative; others hold that Soviet decision-making ran independently of RFE output.", "why": "It is the founding case study in the ethics of broadcasting into a closed country, where accurate reporting of foreign sympathy can be received by listeners as a promise of rescue.", "srcTitle": "A. Ross Johnson, \"Setting the Record Straight: Role of Radio Free Europe in the Hungarian Revolution of 1956, Woodrow Wilson International Center for Scholars", "srcUrl": "https://www.wilsoncenter.org/sites/default/files/media/documents/publication/happ.op-3.pdf", "key": false, "sum": "During the Hungarian Revolution, RFE's Hungarian Service was accused of inciting revolt and of implying Western military help was coming."}, {"year": "24 May 1960", "place": "Egypt", "h": "Nasser nationalises every newspaper and magazine in Egypt", "body": "The state chose editors and defined media content directly. The measure followed the abolition of political parties and completed the subordination of public communication to the Free Officers' regime.", "why": "Nationalisation rather than censorship became the dominant Arab-world model of press control, and its institutional residue still shapes state media ownership across the region.", "srcTitle": "History, Media Ownership Monitor Egypt, Reporters Without Borders", "srcUrl": "https://egypt.mom-rsf.org/en/context/history/", "key": false, "sum": "A presidential decree of 24 May 1960 nationalised all Egyptian newspapers and magazines, placing them under full state management."}], "n": 1}, {"years": "1961–1975", "title": "The licence to publish became the state's sharpest instrument, and the carbon copy became the answer to it.", "framing": "Across three continents governments discovered that they did not need to argue with a newspaper if they could simply revoke its permit, place a censor at its desk, or seize its presses at dawn. Indonesia, Brazil, the Philippines, Chile and India all did versions of the same thing within a decade. The counter-technology was deliberately humble; a typewriter, carbon paper, and six copies at a time.", "events": [{"year": "1965–1966", "place": "Indonesia", "h": "Indonesia's New Order bans a third of the country's press", "body": "Press publications fell from 609 in 1964 to 406 by 1966, and magazines from 163 to 117. Hundreds of journalists were arrested, dismissed or subjected to violence, with the state news agency Antara losing roughly 30% of its editorial staff.", "why": "The Basic Press Law of 1966 then converted the purge into permanent architecture, dual publishing and printing permits revocable without any court, which is how the New Order controlled information for thirty-two years.", "srcTitle": "Indonesian Press Freedom during the New Order Period (1966-1998), International Journal of Media and Communication Research", "srcUrl": "https://journal.uir.ac.id/index.php/ijmcr/article/download/29410/10087/107352", "key": true, "sum": "After the 30 September 1965 coup attempt, 46 of 163 newspapers were banned for alleged Communist Party links and a further 29 associated with Sukarno were shut."}, {"year": "30 April 1968", "place": "Soviet Union", "h": "A typewritten bulletin starts documenting Soviet repression, issue by issue", "body": "It spread by retyping, six carbon copies at a time, each recipient retyping to make six more, and was smuggled out through diplomatic bags and travellers. Its editors were systematically removed: Natalya Gorbanevskaya arrested in 1969 and confined to a psychiatric hospital in 1970, Sergei Kovalyov sentenced to seven years in 1975, Tatyana Velikanova sentenced to ten years in 1979, and final editor Yury Shikhanovich arrested in November 1983.", "why": "It proved that a censorship monopoly can be broken by a distribution method with no chokepoint to seize; the structural argument later made again by the photocopier, the fax and the mesh network.", "srcTitle": "Underground News in the USSR, A Chronicle of Current Events", "srcUrl": "https://chronicle-of-current-events.com/2018/03/03/underground-news-in-the-ussr/", "key": true, "sum": "The first issue of A Chronicle of Current Events appeared on 30 April 1968; 64 issues circulated before the last, dated 30 June 1982, and a 65th was prepared but never released."}, {"year": "21 August – 13 September 1968", "place": "Czechoslovakia", "h": "Czechoslovak Radio keeps broadcasting after Soviet tanks take the building", "body": "When Warsaw Pact forces invaded overnight on 20–21 August, hundreds of unarmed Prague citizens defended the radio building and destroyed three of six Soviet tanks before the invaders seized it on the morning of 22 August. Free broadcasting continued from hidden locations as the country's only unbiased news source until 13 September 1968, when full censorship was reinstated.", "why": "Three weeks of clandestine national broadcasting under occupation showed that control of a transmitter building is not the same as control of the airwaves; and the reinstatement of censorship three weeks later showed how quickly that gap closes.", "srcTitle": "Radio with a human face (1968), Czech Radio", "srcUrl": "https://www.czech.radio/radio-a-human-face-1968-8582704", "key": false, "sum": "Parliament had dissolved strict censorship at the beginning of 1968, opening previously forbidden political debate."}, {"year": "13 December 1968", "place": "Brazil", "h": "Brazil's AI-5 puts permanent censors inside every newsroom", "body": "More than 300 politicians were expelled from Congress in the first year. Censors became permanent fixtures in newsrooms, and shows, plays and cultural events required vetting; Jornal do Brasil famously ran a coded front-page weather report beginning \"Weather forecast – dark times.\"", "why": "AI-5 industrialised prior restraint in Latin America by moving the censor from the ministry into the newsroom, making self-censorship the daily operating condition rather than an occasional event.", "srcTitle": "50 Years Ago, Brazil Virtually Legalized Torture and Censorship, Americas Quarterly", "srcUrl": "https://www.americasquarterly.org/article/50-years-ago-brazil-virtually-legalized-torture-and-censorship/", "key": true, "sum": "Institutional Act Number Five, signed 13 December 1968 by President Artur da Costa e Silva, shuttered Congress, allowed the closure of state assemblies and city councils, stripped political rights for ten years and denied habeas corpus for political crimes; those arrested on suspicion of subversion could contact no one for the first ten days."}, {"year": "30 June 1971", "place": "United States", "h": "The Supreme Court refuses to stop publication of the Pentagon Papers", "body": "v. United States, decided 30 June 1971, the Court ruled 6–3 against the government's attempt to enjoin publication of the classified Defense Department study of Vietnam policy, holding that the government had not met the heavy burden required to justify prior restraint. The nine justices produced nine separate opinions, leaving the precise scope of the rule unsettled. The decision barred the injunction but did not immunise the leaker: Daniel Ellsberg was prosecuted, and his case collapsed in 1973 over government misconduct.", "why": "It established in the strongest terms available that stopping publication is constitutionally harder than punishing it afterwards; a distinction every subsequent leak case, including WikiLeaks and Snowden, has turned on.", "srcTitle": "New York Times Co. v. United States, 403 U.S. 713 (1971), Justia US Supreme Court Center", "srcUrl": "https://supreme.justia.com/cases/federal/us/403/713/", "key": false, "sum": "In New York Times Co."}, {"year": "21–22 September 1972", "place": "Philippines", "h": "Marcos seizes the broadcasters on the first night of martial law", "body": "1, dated 22 September 1972, authorised military takeover of major media outlets on the grounds of preventing propaganda against the government; Letter of Instruction No. 1-A on 28 September sequestered ABS-CBN and the Associated Broadcasting Corporation, including three Manila radio stations, sister stations in four cities and television channels in Davao and Cebu. Nearly 10,000 media employees lost their jobs. Publishers and editors including Chino Roces, Teodoro Locsin Sr., Maximo Soliven and Amando Doronila were arrested without due process; only crony-run outlets such as the Daily Express and Kanlaon Broadcasting were permitted to operate.", "why": "It is the clearest demonstration that a modern coup's first military objective is the transmitter, not the palace; and that ownership transfer, not censorship, is the durable method.", "srcTitle": "FAST FACTS: How Marcos silenced, controlled the media during Martial Law, Rappler", "srcUrl": "https://www.rappler.com/newsbreak/iq/how-marcos-silenced-media-press-freedom-martial-law/", "key": false, "sum": "Letter of Instruction No."}, {"year": "11 September 1973", "place": "Chile", "h": "Chile's junta closes the left-wing press on the morning of the coup", "body": "Clarín's workshops were formally expropriated by Decree No. 580 on 24 April 1975. Public burnings of books deemed subversive followed and are well documented, though inventories of what was destroyed remain incomplete.", "why": "Closing the mass-circulation press within hours, before any censorship regime existed, showed that the fastest form of information control is simply physical seizure.", "srcTitle": "Clarín, Puro Chile y El Siglo: Tres diarios cerrados de golpe, Museo de Prensa, Universidad Diego Portales", "srcUrl": "https://museodeprensa.udp.cl/clarin-puro-chile-y-el-siglo-tres-diarios-cerrados-de-golpe/", "key": false, "sum": "The army entered the offices of Clarín in the early hours of 11 September 1973 and closed it under Bando N°1; Puro Chile was closed the same day under the same order, and El Siglo was raided by soldiers and its presses confiscated after an edition headlined \"Cada cual en su puesto de combate.\" Clarín had a daily circulation of around 180,000 and over 400,000 on Sundays; El Siglo around 25,000."}, {"year": "25–26 June 1975", "place": "India", "h": "Delhi's newspaper presses lose power the night the Emergency begins", "body": "Governor Krishan Chand, preventing morning editions from reporting the Emergency declaration and the arrest of opposition leaders; the Hindustan Times and Statesman offices, in NDMC areas, escaped and printed limited runs. Censorship guidelines followed on 3 July, 4 July and 13 July 1975, prohibiting blank editorial spaces and even quotations from Gandhi or Tagore. On 29 July 1975 newspapers were formally classified as \"friendly,\" \"hostile\" or \"neutral,\" with the Indian Express and The Statesman placed in the hostile category.", "why": "It remains the reference case for how quickly a functioning democratic press can be silenced by administrative means; an electricity order, a guideline memo and a list.", "srcTitle": "Predicament of the press during the Emergency, The Leaflet", "srcUrl": "https://theleaflet.in/forty-seven-years-since-declaration-of-emergency/predicament-of-the-press-during-the-emergency", "key": true, "sum": "Power to the newspaper offices on Bahadur Shah Zafar Marg was cut on the night of 25–26 June 1975 on the orders of Lt."}, {"year": "1 August 1975", "place": "Helsinki, Finland", "h": "Thirty-five states sign human-rights language the Soviet bloc would regret", "body": "Its third basket covered human rights including freedom of emigration, family reunification, cultural exchange and freedom of the press. Moscow accepted the language as the price of Western recognition of post-war borders, treating it as non-binding.", "why": "It handed dissidents a text their own governments had signed, converting human rights from foreign criticism into a domestic compliance question; the basis on which Charter 77 and the Moscow Helsinki Group were built.", "srcTitle": "Helsinki Final Act, 1975, Office of the Historian, US Department of State", "srcUrl": "https://history.state.gov/milestones/1969-1976/helsinki", "key": false, "sum": "The Helsinki Final Act was signed on 1 August 1975 by 35 states, every European country except Albania, plus the United States and Canada."}], "n": 2}, {"years": "1976–1989", "title": "Reproduction got cheaper faster than repression could scale, and in 1989 the gap broke open.", "framing": "This is the era in which the cost of copying collapsed. Carbon paper gave way to offset presses hidden in flats, then to photocopiers, then to fax machines, while states responded by registering duplicating equipment and cutting the telephone network outright. By November 1988 the Soviet Union had stopped jamming; a year later the information monopoly it had defended was gone.", "events": [{"year": "19 October 1977", "place": "South Africa", "h": "Black Wednesday bans two newspapers and nineteen organisations at once", "body": "The World's editor Percy Qoboza was detained and held for five months without trial under section 10 of the Internal Security Act at Modderbee Prison. The crackdown followed press coverage of Steve Biko's death in police custody the previous month.", "why": "Banning the reporting and the reporters on the same day made explicit what the apartheid state usually obscured; that the censorship and the killings were a single system.", "srcTitle": "Black Wednesday, the banning of 19 Black Consciousness Movement Organisations, South African History Online", "srcUrl": "https://sahistory.org.za/dated-event/black-wednesday-banning-19-black-consciousness-movement-organisations", "key": false, "sum": "On 19 October 1977 the apartheid government banned 19 Black Consciousness Movement organisations and the newspapers The World and Weekend World."}, {"year": "1976–1983", "place": "Argentina", "h": "Ninety-eight Argentine journalists are killed or disappeared", "body": "The junta banned an eclectic list of material including Saint-Exupéry's The Little Prince, the Beatles, modern mathematics and Greek philosophers. Overall death and disappearance totals for the period are contested, with human rights organisations citing more than 30,000 and other estimates considerably lower.", "why": "Argentina pioneered censorship by disappearance, no banning order to appeal, no closure to report, just an absence that taught every remaining newsroom what not to print.", "srcTitle": "On 30th anniversary of coup, a tribute to the 98 journalists missing or killed during the military dictatorship, Reporters Without Borders", "srcUrl": "https://rsf.org/en/30th-anniversary-coup-tribute-98-journalists-missing-or-killed-during-military-dictatorship", "key": false, "sum": "Reporters Without Borders records 98 journalists lost between 1973 and 1980, 83 disappeared and 15 murdered, spanning the Peronist period and the dictatorship that took power on 24 March 1976."}, {"year": "1 January 1977", "place": "Czechoslovakia", "h": "Charter 77 turns Helsinki's own text against the Czechoslovak state", "body": "It reached the public through the New York Times, Le Monde and Frankfurter Allgemeine Zeitung in early January 1977 and circulated domestically as typescript samizdat. By 1989 it had gathered roughly 2,000 signatures and published 572 documents; its leading figures were imprisoned and its signatories harassed throughout.", "why": "It established legalism as a dissident tactic, demanding only that a government obey the instruments it had ratified, which made the movement far harder to characterise as subversion.", "srcTitle": "Gregor Feindt, \"Prague, 1977: Charter 77, Historical Human Rights Atlas, Leibniz Institute of European History", "srcUrl": "https://hhr-atlas.ieg-mainz.de/articles/feindt-prague", "key": true, "sum": "Published on 1 January 1977 with 242 original signatories, Charter 77 invoked the two UN human rights covenants Czechoslovakia had signed in 1968 and reaffirmed at Helsinki in 1975."}, {"year": "13 December 1981", "place": "Poland", "h": "Martial law cuts every private telephone and telex line in Poland", "body": "Only two daily newspapers remained, the Communist Party organ and the army's daily, and television and radio were consolidated into a single military-controlled channel. Foreign journalists were left unable to file; about a week in, one censored telex line was permitted, usable only for reports based on state media, and telephone service returned around Christmas.", "why": "It is the first modern case of a government disconnecting an entire national communications network as a counter-protest measure; the direct ancestor of the internet shutdown.", "srcTitle": "'All the Telephone and Telex Lines are Disconnected' – RFE and the 1981 Martial Law in Poland, Blinken OSA Archivum", "srcUrl": "https://www.archivum.org/entries/blog/all-the-telephone-and-telex-lines-are-disconnected---rfe-and-the-1981-martial-law-in-poland", "key": true, "sum": "When martial law was declared on 13 December 1981, all private telephone and telex lines were cut, mail was censored and the state took over communications and media networks."}, {"year": "26 April 1986", "place": "Soviet Union (Ukrainian SSR)", "h": "Moscow hides a reactor explosion for nearly three days", "body": "Western embassies were not notified until the radiation cloud reached Sweden the following Monday. Radiation levels published by the Soviet press were 1 percent or less of what authorities knew them to be; over 100,000 people were eventually evacuated.", "why": "The coverup discredited glasnost at the moment of its announcement and demonstrated that information suppression in a networked physical environment fails; the radiation reported itself.", "srcTitle": "Chernobyl Disaster Coverup, EBSCO Research Starters, Communication and Mass Media", "srcUrl": "https://www.ebsco.com/research-starters/communication-and-mass-media/chernobyl-disaster-coverup", "key": false, "sum": "The Chernobyl reactor exploded on 26 April 1986 and the Soviet government kept the news out of the press for almost three days, despite knowing within hours what had happened."}, {"year": "30 November 1988", "place": "Soviet Union", "h": "After thirty-nine years the Soviet Union switches off the jammers", "body": "At its height the bloc's jamming apparatus involved thousands of transmitters and cost more than the entire worldwide budget of the station it was blocking. Jamming of US-funded broadcasts continued elsewhere: China, Cuba, Vietnam and North Korea were still jamming as of 2020, and Iran stopped jamming Radio Farda in 2019.", "why": "The decision to stop was an admission that the information blockade had become more expensive to maintain than the information was dangerous to admit; and it preceded the political collapse by twelve months.", "srcTitle": "Soviet Bloc Jamming of Western Freedom Radios, Cold War Radio Museum", "srcUrl": "https://www.coldwarradiomuseum.com/soviet-block-jamming-of-western-freedom-radios/", "key": true, "sum": "The USSR stopped jamming Western broadcasts on 30 November 1988, ending an effort begun against VOA on 24 April 1949."}, {"year": "20 May – 4 June 1989", "place": "China", "h": "Beijing cuts CNN's satellite feed as martial law is declared", "body": "Correspondents were detained during the following weeks, including Hong Kong reporters and a CBS correspondent, and reporters were expelled in mid-June. Crews smuggled footage out by disassembling it frame by frame and sending it over ordinary phone lines for reconstruction abroad.", "why": "It was the first time a government cut a live international satellite broadcast mid-transmission, establishing that transnational media could be severed at the uplink; and the resulting censorship of \"June 4\" inside China has been continuously maintained since.", "srcTitle": "China declares martial law, UPI Archives, 20 May 1989", "srcUrl": "https://www.upi.com/Archives/1989/05/20/China-declares-martial-law/8922611640000/", "key": false, "sum": "On 20 May 1989, as martial law was declared in Beijing, Chinese authorities told American television networks they could no longer use private satellite transmission stations and forced CNN to end live broadcasting; the final moments of the feed showed network staff negotiating unsuccessfully with officials."}, {"year": "1989", "place": "Hong Kong → mainland China", "h": "Hong Kong students fax the news back into a blockaded China", "body": "Claims about the volume of faxes sent vary widely and no reliable count exists.", "why": "It marked the point at which ordinary office equipment became a cross-border publishing tool, a pattern repeated by the photocopier in Eastern Europe and by the smartphone thirty years later.", "srcTitle": "Students in Hong Kong used fax machines to fight Chinese censorship of Tiananmen Square, Quartz", "srcUrl": "https://qz.com/1688553/how-a-hong-kong-fax-machine-informed-millions-of-chinese-in-1989", "key": false, "sum": "As the mainland crackdown proceeded, Hong Kong students used fax machines, then among the most advanced communications technologies available, to push news of Tiananmen into China, choosing that over conventional protest specifically to break the news blockade."}], "n": 3}, {"years": "1990–2000", "title": "The open decade wrote the rules for closing the internet at exactly the same time it opened it.", "framing": "The decade is remembered for the web, satellite television and the end of the one-party press in a dozen countries. It should also be remembered for the Rwandan radio that organised a genocide, for China's first internet regulations in 1996, and for Singapore, Malaysia and Serbia writing the first content-licensing laws for online speech. The tools of the open internet and the tools for filtering it were built in the same five years.", "events": [{"year": "1993 (bans and closures 1994)", "place": "Nigeria", "h": "Abacha proscribes Nigeria's three largest independent newspaper groups", "body": "The Guardian was then the country's most influential national daily. Human Rights Watch documented at least 14 media workers arrested, editors, reporters, photographers and a newspaper vendor, and stated the list was not exhaustive.", "why": "Proscription by decree, rather than prosecution of articles, became the standard West African method for removing a press without the inconvenience of a trial.", "srcTitle": "Nigeria: The Dawn of a New Dark Age\" (October 1994, Vol. 6, No. 8) ,  Human Rights Watch/Africa", "srcUrl": "https://www.hrw.org/reports/pdfs/n/nigeria/nigeria94o.pdf", "key": false, "sum": "Decrees 6, 7 and 8, announced together on 5 September 1994, proscribed the Concord group and the Punch group from 10 June and the Guardian group from 14 August, each for six months, with publishers' premises ordered sealed."}, {"year": "April–July 1994", "place": "Rwanda", "h": "A radio station broadcasts a genocide into being", "body": "It was the first international judgment on media and genocide since Julius Streicher was tried at Nuremberg, and the tribunal drew an explicit line between discussing ethnic consciousness and promoting ethnic hatred.", "why": "The Media Trial established in international law that broadcasting can be a mode of committing atrocity, which is why every subsequent hate-speech-versus-free-expression argument runs through Rwanda.", "srcTitle": "Three Media Leaders convicted for Genocide, United Nations International Criminal Tribunal for Rwanda", "srcUrl": "https://unictr.irmct.org/en/news/three-media-leaders-convicted-genocide", "key": true, "sum": "Radio Télévision Libre des Mille Collines broadcast dehumanising messages against Tutsis alongside the newspaper Kangura, which published the \"Ten Commandments of the Hutu.\" On 3 December 2003 the ICTR convicted RTLM founder Ferdinand Nahimana and Kangura editor Hassan Ngeze to life imprisonment and RTLM board member Jean-Bosco Barayagwiza to 35 years."}, {"year": "21 June 1994", "place": "Indonesia", "h": "Suharto bans Tempo, DeTIK and Editor on one day", "body": "The bans were imposed by permit revocation under the 1966 press licensing system, requiring no court proceedings. It was the largest single strike against the Indonesian press since the Malari bans of 1974, which had taken 12 publications at once.", "why": "The 1994 bans destroyed the New Order's claim to a managed but functioning press and helped produce the underground journalist networks that outlived Suharto's fall four years later.", "srcTitle": "Indonesian Press Freedom during the New Order Period (1966-1998), International Journal of Media and Communication Research", "srcUrl": "https://journal.uir.ac.id/index.php/ijmcr/article/download/29410/10087/107352", "key": false, "sum": "On 21 June 1994 the New Order banned three major publications simultaneously: Tempo, with a circulation of 187,000; DeTIK, 215,000; and Editor, 80,000."}, {"year": "1 November 1996", "place": "Qatar", "h": "Al Jazeera launches and breaks the Arab state-media monopoly", "body": "Its transmissions were at times blocked by other Arab countries, and its critics argued it inflamed rather than informed. Accounts of the exact launch date vary between sources, with 1 November 1996 the most commonly cited.", "why": "A single satellite channel outside any given government's jurisdiction ended the ability of Arab states to control what their own populations saw about themselves; the precondition for 2011.", "srcTitle": "Al Jazeera, Encyclopaedia Britannica", "srcUrl": "https://www.britannica.com/topic/Al-Jazeera", "key": true, "sum": "Al Jazeera was founded in 1996 by Sheikh Hamad ibn Khalifa Al Thani, Emir of Qatar, with guaranteed government financial backing for its first five years; continuous round-the-clock programming began in 1999."}, {"year": "1996 (regulations); 1998 (Golden Shield)", "place": "China", "h": "China writes internet rules two years after connecting to the internet", "body": "In 1998 the Ministry of Public Security launched the Golden Shield project, a national filter designed to block politically sensitive content from entering the domestic network. Blocking subsequently expanded far beyond political content to gaming, photo-sharing and social platforms.", "why": "China decided before mass adoption that the network would be a bounded national space rather than a global one, and every filtering regime built since has been a variation on that choice.", "srcTitle": "The Evolution of China's Great Firewall: 21 Years of Censorship, Global Voices Advox", "srcUrl": "https://advox.globalvoices.org/2017/08/30/the-evolution-of-chinas-great-firewall-21-years-of-censorship/", "key": true, "sum": "Beijing enacted interim provisions governing computer information in 1996, establishing the first regulatory framework for internet content."}, {"year": "26 June 1997", "place": "United States", "h": "The Supreme Court strikes down the first US internet censorship law", "body": "American Civil Liberties Union, decided 26 June 1997, the Court struck down the anti-indecency provisions of the 1996 Communications Decency Act as unconstitutionally vague and overbroad. The ruling held that the internet was entitled to the highest level of First Amendment protection, closer to print than to broadcast, which had long been subject to greater regulation on scarcity grounds.", "why": "Assigning the internet print-level rather than broadcast-level protection in its first major constitutional test set the default for two decades of US platform law.", "srcTitle": "Reno v. American Civil Liberties Union (1997), The First Amendment Encyclopedia, Middle Tennessee State University", "srcUrl": "https://firstamendment.mtsu.edu/article/reno-v-american-civil-liberties-union/", "key": false, "sum": "In Reno v."}, {"year": "October 1998", "place": "Serbia (FR Yugoslavia)", "h": "Milošević fines newspapers into silence under an emergency information decree", "body": "On 23 October, Slavko Ćuruvija, owner of Dnevni Telegraf and Evropljanin, along with the editor and publisher, were found guilty of jeopardising Serbia's territorial integrity and fined 2,400,000 dinars, about US$230,000. Numerous other publications received comparable fines through November and December 1998. Ćuruvija was murdered in Belgrade in April 1999.", "why": "Ruinous fines rather than outright bans became the preferred authoritarian technique in nominally pluralist states, because a bankrupted newspaper requires no censorship order to explain.", "srcTitle": "Deepening Authoritarianism in Serbia: The Purge of the Universities, Human Rights Watch", "srcUrl": "https://www.hrw.org/reports/1999/serbia/Serbia99-02.htm", "key": false, "sum": "An emergency decree announced in early October 1998, later embodied in the Public Information Act passed that month, gave the government power to suppress foreign broadcasts of a \"political-propaganda nature\" and sharply raised fines for domestic media."}, {"year": "20–27 April 2000", "place": "Iran", "h": "Iran's judiciary shuts thirteen publications in a single week", "body": "Thirteen newspapers and magazines were ordered shut indefinitely on 23–24 April, three more dailies on 27 April, and roughly 30 newspapers had been closed by the end of the year. Journalists were jailed, Mashallah Shamsolvaezin sentenced to 30 months on 10 April, Akbar Ganji arrested on 22 April; with at least six in prison at year's end, and Parliament passed amendments requiring prior judicial permission before a banned title could relaunch under a new name.", "why": "It ended the reformist press experiment and established the pattern of judicial rather than executive censorship, which insulates the government from direct responsibility for each closure.", "srcTitle": "Attacks on the Press 2000: Iran, Committee to Protect Journalists", "srcUrl": "https://cpj.org/2001/03/attacks-on-the-press-2000-iran/", "key": false, "sum": "On 20 April 2000 Supreme Leader Ali Khamenei attacked the reformist press; two days later the judiciary began closing titles."}], "n": 4}, {"years": "2001–2012", "title": "After 2001 the security state went digital, and governments discovered they could simply switch the network off.", "framing": "Counter-terrorism law expanded state access to communications data in democracies while authoritarian governments learned that the internet had a small number of physical chokepoints. Nepal in 2005 and Burma in 2007 were the proof-of-concept; Egypt in 2011 was the demonstration at scale. By 2012 shutting down the network during unrest was an established, if still shocking, instrument of government.", "events": [{"year": "26 October 2001", "place": "United States", "h": "The USA PATRIOT Act expands surveillance access to communications records", "body": "Section 215 in particular later became the claimed legal basis for bulk telephone metadata collection, a use that was not publicly known until 2013 and that a federal appeals court found in 2015 the statute did not authorise.", "why": "It normalised the argument that communications metadata is an investigative resource rather than private information, which is the premise that made population-scale surveillance administratively possible.", "srcTitle": "H.R.3162 ,  Uniting and Strengthening America by Providing Appropriate Tools Required to Intercept and Obstruct Terrorism (USA PATRIOT ACT) Act of 2001, Congress.gov", "srcUrl": "https://www.congress.gov/bill/107th-congress/house-bill/3162", "key": true, "sum": "Signed into law on 26 October 2001, the Act broadened government authority to obtain communications and business records, expanded the use of National Security Letters, eased the use of pen registers and trap-and-trace devices on internet traffic, and loosened restrictions on sharing intelligence and criminal investigative material."}, {"year": "27 April 2005", "place": "China", "h": "Yahoo data helps send a Chinese journalist to prison for ten years", "body": "On 27 April 2005 he was sentenced to ten years for disclosing state secrets. Yahoo! Holdings (Hong Kong) Limited supplied customer information linked to an IP address, including a telephone number and the address of the Hunan Contemporary Business News publishing house in Changsha, which helped establish that the email originated at his workplace.", "why": "It was the first case to make concrete that a foreign platform's local subsidiary is a point of state leverage, and it began the corporate-complicity debate that runs through to lawful-access and data-localisation fights today.", "srcTitle": "Yahoo! Cited in Court Decision as Providing Evidence in Shi Tao State Secrets Trial, Congressional-Executive Commission on China", "srcUrl": "https://www.cecc.gov/publications/commission-analysis/yahoo-cited-in-court-decision-as-providing-evidence-in-shi-tao", "key": false, "sum": "Shi Tao, a newspaper editor, emailed notes from an editorial meeting to an organisation in New York on 20 April 2004."}, {"year": "1 February 2005", "place": "Nepal", "h": "Nepal's king cuts phones and all six ISPs during a coup", "body": "Telephone lines were blocked, the mobile network switched off and all six internet service providers shut down by the army. Soldiers occupied newsrooms before the king's speech had ended, Kantipur's editor described 40 or 50 armed soldiers spread out \"as if in battle order\", and remained for up to a week; news reporting on FM radio, the primary rural information source employing roughly 1,200 FM journalists, was shut down entirely, and 10 journalists were still in custody in mid-April.", "why": "This is the first documented case of a government switching off a national internet as a deliberate coup instrument, four years before the tactic acquired a name.", "srcTitle": "A country silenced, Committee to Protect Journalists, April 2005", "srcUrl": "https://cpj.org/reports/2005/04/nepal-05-main/", "key": true, "sum": "King Gyanendra dismissed the government and declared a state of emergency at about 10:30am on 1 February 2005, suspending press freedom."}, {"year": "29 September – 13 October 2007", "place": "Burma (Myanmar)", "h": "Burma's junta disconnects the country to end the Saffron Revolution", "body": "The two state-controlled ISPs cut connectivity entirely from 29 September to 4 October, with a single six-hour window on 1 October, then ran regulated outages until stable service resumed on 13 October; speeds were afterwards throttled to 256 Kbps specifically to prevent video uploads. Burma then had under 1 percent internet penetration, roughly 300,000 users, most using about 200 internet cafés concentrated in Rangoon.", "why": "It demonstrated that where the state owns the gateways a full national disconnection takes hours, and that throttling is a subtler successor to blackout; a lesson every subsequent shutdown regime has applied.", "srcTitle": "Pulling the Plug: A Technical Review of the Internet Shutdown in Burma, OpenNet Initiative", "srcUrl": "https://opennet.net/research/bulletins/013", "key": false, "sum": "Traffic fell to 14 percent of the previous week's average on 28 September 2007, 7 percent on 29 September and zero on 30 September."}, {"year": "July 2009 – May 2010", "place": "Xinjiang, China", "h": "China cuts an entire region off the internet for ten months", "body": "Services were partially restored from December 2009, text messaging and international calls in January 2010, and full internet access was announced in May 2010, ten months later. The Congressional-Executive Commission on China assessed that the restrictions exceeded permissible limits on free expression under international standards.", "why": "A ten-month regional blackout proved a state could sustain a shutdown indefinitely if it accepted the economic cost, breaking the assumption that shutdowns are necessarily short.", "srcTitle": "Internet Available in Xinjiang, But Controls Over Information Remain, Congressional-Executive Commission on China", "srcUrl": "https://www.cecc.gov/publications/commission-analysis/internet-available-in-xinjiang-but-controls-over-information-remain", "key": false, "sum": "Internet access across the Xinjiang Uyghur Autonomous Region was cut on 7 July 2009 after the Urumqi riots, along with text messaging and international phone calls; the Communist Party secretary of Urumqi said the aim was to quell the riot quickly and stop violence spreading."}, {"year": "28 November 2010", "place": "United States / international", "h": "WikiLeaks and five newspapers begin publishing 251,287 diplomatic cables", "body": "Amazon withdrew hosting and PayPal, Visa and Mastercard cut payment processing within days, without any court order requiring them to do so. Chelsea Manning, the source, was convicted in 2013 and sentenced to 35 years, commuted in 2017.", "why": "The financial and hosting blockade showed that infrastructure providers can suppress a publication more quickly and with less accountability than any censorship statute; the first clear demonstration of privatised censorship at internet scale.", "srcTitle": "Secret US Embassy Cables, The Guardian", "srcUrl": "https://www.theguardian.com/world/series/us-embassy-cables-the-documents", "key": false, "sum": "Publication of the US State Department cables began on 28 November 2010, coordinated with Der Spiegel, El País, Le Monde, The Guardian and The New York Times."}, {"year": "27 January – 2 February 2011", "place": "Egypt", "h": "Egypt withdraws itself from the global internet for five days", "body": "Mobile networks were cut in parallel. The OECD estimated direct costs of at minimum US$90 million in lost telecommunications and internet revenue, excluding knock-on losses to e-commerce, tourism and call centres. Mubarak resigned on 11 February, nine days after connectivity returned.", "why": "Egypt made the shutdown a globally legible political act, and, by failing to stop the protests, established the counter-argument that shutdowns visibly escalate rather than contain unrest.", "srcTitle": "OECD Estimates Economic Impact of Shutting Down Internet and Mobile Phone Services in Egypt, CIPESA", "srcUrl": "https://cipesa.org/2011/04/oecd_estimates_economic_impact_of_shutting_down_internet_and_mobile_phone_services_in_egypt_/", "key": true, "sum": "Beginning late on 27 January 2011, Egyptian ISPs withdrew their routes from the global routing table; the Noor Group, which hosted the Egyptian Stock Exchange, was a conspicuous exception and kept all 83 of its routes live."}, {"year": "2006–2012", "place": "Mexico", "h": "Cartel violence makes Mexico the hemisphere's deadliest country for reporters", "body": "Mexico ranks consistently in the top ten of CPJ's Global Impunity Index, usually just below active war zones. In most cases police investigations either stalled or produced no insight into motive.", "why": "Mexico demonstrated that information can be suppressed without any censorship law at all, by making the cost of reporting on organised crime lethal, and the cost of killing a reporter effectively zero.", "srcTitle": "Amid spike in journalist killings in Mexico, CPJ urges federalizing cases to end impunity, Committee to Protect Journalists, August 2026", "srcUrl": "https://cpj.org/2026/08/amid-spike-in-journalist-killings-in-mexico-cpj-urges-federalizing-cases-to-end-impunity/", "key": false, "sum": "CPJ records 166 journalists and media workers killed in Mexico since 1992, of which 97 are classified as unconfirmed because the organisation could not establish a direct link to the victim's work."}], "n": 5}, {"years": "2013–2020", "title": "Surveillance went to population scale, and cutting the network became routine statecraft.", "framing": "Snowden established that bulk collection was real; Pegasus established that targeted infection was commercially available to any government that could pay. Meanwhile the shutdown moved from scandal to routine, rising from 75 documented incidents in 2016 to 313 in 2025. The period ends with Iran running the longest national blackout ever measured in a connected society.", "events": [{"year": "5–6 June 2013", "place": "United States / United Kingdom", "h": "Snowden documents reveal bulk collection of communications records", "body": "Subsequent disclosures covered the NSA's and GCHQ's upstream collection, tapping of undersea cables, and efforts against encryption standards. The Guardian and The Washington Post shared the 2014 Pulitzer Prize for Public Service for the reporting; Snowden was charged under the Espionage Act and has remained outside US jurisdiction since.", "why": "It converted mass surveillance from a hypothesis into a documented fact, and produced the direct consequences, default HTTPS, end-to-end encrypted messaging at consumer scale, that now define the encryption policy fight.", "srcTitle": "Snowden Timeline, Government Accountability Project", "srcUrl": "https://whistleblower.org/snowden-timeline/", "key": true, "sum": "The first story, published 5 June 2013, disclosed a secret court order requiring Verizon to hand over telephone metadata for millions of US customers; PRISM followed on 6 June."}, {"year": "21 March – 3 April 2014", "place": "Turkey", "h": "Turkey blocks Twitter, then its own top court overturns the ban", "body": "The Constitutional Court ruled the ban breached freedom of expression, and it was lifted on 3 April 2014 once the decision was published in the Official Gazette. The Constitutional Court separately rejected the YouTube ban on 29 May 2014.", "why": "It was the first time a platform-wide block in a G20 democracy was reversed by that country's own constitutional court, establishing a judicial check that has since been tested repeatedly and unevenly.", "srcTitle": "Turkey lifts Twitter ban after court ruling, Al Jazeera", "srcUrl": "https://www.aljazeera.com/news/2014/4/3/turkey-lifts-twitter-ban-after-court-ruling", "key": false, "sum": "Turkey blocked Twitter on 21 March 2014 to stop the spread of leaked wiretap recordings of senior officials ahead of local elections, with Prime Minister Erdoğan vowing to \"root out\" the network; YouTube was blocked about a week later."}, {"year": "1 July 2016", "place": "Geneva (UN Human Rights Council)", "h": "The UN condemns internet shutdowns for the first time", "body": "A number of states attempted to weaken the text through amendments and failed. The resolution is not binding.", "why": "It gave shutdown-affected populations and litigators a specific international standard to cite, which is why subsequent shutdowns have been fought in national courts in India, Sudan, Cameroon and Togo rather than only in press releases.", "srcTitle": "U.N. passes landmark resolution condemning internet shutdowns, Access Now", "srcUrl": "https://www.accessnow.org/press-release/un-passes-resolution-condemning-internet-shutdowns/", "key": false, "sum": "Resolution A/HRC/32/L.20, adopted by consensus on 1 July 2016, condemned measures to intentionally prevent or disrupt access to information online and reaffirmed that the same rights people have offline must be protected online."}, {"year": "17 January – 20 April 2017", "place": "Anglophone Cameroon", "h": "Cameroon cuts its English-speaking regions off for 93 days", "body": "The shutdown was lifted after international pressure including from the UN. A US-based Cameroonian activist with telecommunications expertise, Judith Nwana, estimated the first shutdown alone cost at least US$38 million; a second, more targeted shutdown in October 2017 blocked social media rather than the whole network.", "why": "Targeting a shutdown at a linguistic minority rather than a whole country introduced the regional, population-specific blackout that has since become the dominant African pattern.", "srcTitle": "Cameroon internet shutdowns cost Anglophones millions, Al Jazeera", "srcUrl": "https://www.aljazeera.com/news/2018/1/26/cameroon-internet-shutdowns-cost-anglophones-millions", "key": false, "sum": "Cameroon cut internet access to its Anglophone regions for 93 days from January to April 2017, in response to strikes by Anglophone teachers, lawyers and students over discrimination."}, {"year": "3–12 June 2019 (shutdown continued into July)", "place": "Sudan", "h": "Sudan's generals cut the internet as they clear a protest camp", "body": "Transitional Military Council spokesman Shamseddin Kabashy confirmed responsibility on Al-Jazeera, saying services were stopped \"for a limited period, at our discretion.\" A Sudanese court later ordered a telecoms company to restore service, an order the military resisted.", "why": "Sudan is the clearest documented case of a shutdown timed to a massacre, and it made concealment-of-violence, rather than crowd control, the standard analytical frame for reading shutdown timing.", "srcTitle": "Sudan: End Network Shutdown Immediately, Human Rights Watch", "srcUrl": "https://www.hrw.org/news/2019/06/12/sudan-end-network-shutdown-immediately", "key": true, "sum": "Mobile internet disruptions began on 3 June 2019, the day security forces attacked the Khartoum sit-in and killed more than 100 people according to Human Rights Watch; remaining fixed-line connections were cut on 10 June, producing a near-total restriction."}, {"year": "5 August 2019 – 5 February 2021", "place": "Jammu and Kashmir, India", "h": "India runs the longest shutdown ever imposed by a democracy", "body": "Landlines returned on 18 August 2019, postpaid mobile on 14 October 2019, broadband for essential purposes on 15 January 2020, and 4G only on 5 February 2021, 550 days in total, including 213 days of complete outage, affecting roughly 9–10 million people. Economic loss estimates for the region circulate widely and vary by an order of magnitude depending on the conversion used, so no single figure is reliable.", "why": "It destroyed the assumption that democratic accountability limits shutdown duration, and India has led or near-led the global shutdown count almost every year since 2018.", "srcTitle": "Shutdown – India, Internet Society Pulse", "srcUrl": "https://pulse.internetsociety.org/en/shutdowns/india-110/", "key": true, "sum": "The shutdown began on 5 August 2019 alongside the revocation of the region's special status."}, {"year": "16–27 November 2019", "place": "Iran", "h": "Iran shuts the internet and kills 304 protesters in the dark", "body": "Restoration began around 10am on 21 November and was complete by 27 November. Amnesty documented at least 304 people killed during the protest period, at least 100 of them on 16 November, the deadliest day, deaths that occurred while the country was disconnected.", "why": "It is the most fully documented instance of a shutdown used as an operational precondition for lethal force, and it shaped the argument that shutdowns are not merely a rights restriction but an atrocity-enabling measure.", "srcTitle": "Iran: Internet deliberately shut down during November 2019 killings – new investigation, Amnesty International", "srcUrl": "https://www.amnesty.org/en/latest/press-release/2020/11/iran-internet-deliberately-shut-down-during-november-2019-killings-new-investigation/", "key": false, "sum": "Cellular operators were ordered to disconnect at around 2pm local time on 16 November 2019; by 7pm the country was in what Amnesty International called digital darkness."}], "n": 6}, {"years": "2021–2026", "title": "Shutdowns stopped being a crisis measure and became a schedule.", "framing": "The blackout is now a planned instrument rather than a panic response: nightly curfews, exam-season cuts, election blackouts, and in one case a national fibre network switched off by decree. Spyware moved from state labs to a commercial market, and the legal response split between the EU writing duties for platforms and a widening group of states writing prison terms for reporting.", "events": [{"year": "1 February 2021 onwards", "place": "Myanmar", "h": "Myanmar's coup runs on nightly national internet curfews", "body": "Facebook services were blocked from 4 February, Twitter from 5 February, Instagram from 10 February and Wikipedia from around 20 February, alongside VPN sites including ProtonVPN and TunnelBear. Access Now recorded 95 shutdowns in Myanmar in 2025, the world's highest, of which roughly 76 were imposed by the junta.", "why": "Myanmar turned the shutdown from an emergency measure into a permanent scheduled utility, which is the model now visible in conflict zones worldwide.", "srcTitle": "Myanmar: Data on internet blocks and internet outages following military coup, OONI", "srcUrl": "https://ooni.org/post/2021-myanmar-internet-blocks-and-outages/", "key": false, "sum": "OONI measured connectivity drops from around 00:20 UTC on 1 February 2021, a near-30-hour total outage from 6 to 7 February, and from 15 February a complete national shutdown every night for around eight hours, between 01:00 and 09:00 local time, synchronised across networks."}, {"year": "18 July 2021", "place": "International (17 media organisations, 10 countries)", "h": "The Pegasus Project exposes spyware sold to governments worldwide", "body": "At least 180 journalists across 20 countries were identified as selected between 2016 and June 2021, with identified NSO Group clients in 11 countries: Azerbaijan, Bahrain, Hungary, India, Kazakhstan, Mexico, Morocco, Rwanda, Saudi Arabia, Togo and the UAE. NSO firmly denied the findings, calling them uncorroborated theories and wrong assumptions, and disputed the significance of the list.", "why": "It established that state-grade phone infection is a purchasable commodity rather than a superpower capability, which is why the surveillance debate has since shifted from intelligence agencies to the spyware market.", "srcTitle": "The Pegasus Project: Massive data leak reveals Israeli NSO Group's spyware used to target activists, journalists, and political leaders globally, Amnesty International USA", "srcUrl": "https://www.amnestyusa.org/press-releases/the-pegasus-project-massive-data-leak-reveals-israeli-nso-groups-spyware-used-to-target-activists-journalists-and-political-leaders-globally/", "key": true, "sum": "Published on 18 July 2021 by Forbidden Stories with technical analysis by Amnesty International's Security Lab and more than 80 journalists from 17 media organisations in 10 countries, the investigation examined a leaked list of 50,000 phone numbers."}, {"year": "21 September – mid-October 2022", "place": "Iran", "h": "Iran imposes a nightly mobile curfew during the Mahsa Amini protests", "body": "OONI and partners measured the three major mobile carriers shutting down from around 4pm local time until roughly midnight for 13 consecutive days from 21 September to 3 October, with further shutdowns on 8, 12 and 15 October, approximately 100 hours of mobile unavailability. WhatsApp and Instagram were blocked from 21 September, Skype, Viber and LinkedIn from 23 September, the Google Play and Apple app stores from 22 September, browser extension repositories from 26 September and encrypted DNS from 20 September.", "why": "The scheduled daily curfew is a deliberate optimisation, enough connectivity to keep the economy running, too little to let a protest organise, and it has become the template for shutdowns in economically integrated states.", "srcTitle": "Technical multi-stakeholder report on Internet shutdowns: The case of Iran amid autumn 2022 protests, OONI", "srcUrl": "https://ooni.org/post/2022-iran-technical-multistakeholder-report", "key": false, "sum": "Restrictions began on 16 September 2022 after Jhina (Mahsa) Amini's death and intensified from 20–21 September."}, {"year": "4 March 2022", "place": "Russia", "h": "Russia criminalises accurate reporting on its own war", "body": "32-FZ, creating Criminal Code Article 207.3 on spreading knowingly false information about the armed forces, with base sentences of up to three years, five to ten years in aggravated circumstances and ten to fifteen years where grave consequences follow; fines run from 700,000 to 5 million rubles, with administrative penalties for \"discrediting\" the military from 30,000 to 500,000 rubles. Further amendments followed on 25 March 2022. International broadcasters including the BBC, CNN and Bloomberg suspended reporting from Russia within days, and most leading independent Russian outlets relocated abroad while scores of journalists left the country.", "why": "By criminalising the description of an event rather than the publication of a secret, Russia created a censorship instrument that reaches every citizen with a phone, not just the press.", "srcTitle": "Understanding the laws relating to 'fake news' in Russia, Committee to Protect Journalists", "srcUrl": "https://cpj.org/wp-content/uploads/2022/07/Guide-to-Understanding-the-Laws-Relating-to-Fake-News-in-Russia.pdf", "key": false, "sum": "On 4 March 2022 Russia adopted Federal Law No."}, {"year": "25 August 2023", "place": "European Union", "h": "The EU imposes systemic-risk duties on nineteen very large platforms", "body": "Designated platforms must identify and mitigate systemic risks including to free expression, conduct annual risk assessments shared with the Commission, provide vetted researchers with access to publicly available data, and stop profiling-based advertising to minors and advertising based on sensitive personal data.", "why": "The DSA created the first binding regulatory regime that treats platform content moderation as a matter of auditable public accountability rather than private terms of service; and the first that non-EU governments now cite as precedent for their own content laws.", "srcTitle": "Digital Services Act takes effect for large online platforms, data.europa.eu, European Commission", "srcUrl": "https://data.europa.eu/en/news-events/news/digital-services-act-takes-effect-large-online-platforms", "key": false, "sum": "The Digital Services Act's obligations for very large online platforms and search engines took effect on 25 August 2023, applying to 19 designated services each with at least 45 million EU users."}, {"year": "17–28 July 2024", "place": "Bangladesh", "h": "Bangladesh cuts mobile internet for eleven days during student protests", "body": "Death tolls are contested: the government reported at least 147, while the student group Students Against Discrimination gave a preliminary count of at least 266, and independent estimates exceeded 200. WhatsApp, Facebook, TikTok and YouTube remained restricted after mobile connectivity was restored.", "why": "The shutdown failed on its own terms, the government it protected fell within a fortnight of the blackout ending, making Bangladesh the strongest recent evidence that shutdowns accelerate rather than suppress political crises.", "srcTitle": "Bangladesh restores mobile internet after 11-day blackout to quell protests, Al Jazeera", "srcUrl": "https://www.aljazeera.com/news/2024/7/28/bangladesh-restores-mobile-internet-after-11-day-blackout-to-quell-protests", "key": false, "sum": "Bangladesh imposed an 11-day mobile internet blackout from 17 to 28 July 2024 during protests over public-sector job quotas; broadband returned on 23 July and 4G mobile at 3pm on 28 July."}, {"year": "29 October – 3 November 2025", "place": "Tanzania", "h": "Tanzania blacks out the internet across a disputed election", "body": "UN human rights experts cited at least 700 extrajudicial killings, while noting other estimates pointing to thousands of potential victims; these are allegations and estimates rather than independently verified counts. The experts said the blackout \"severely curtailed the ability of human rights defenders and journalists\" to document violations. Access Now recorded 8 shutdowns in Tanzania across 2025.", "why": "Tanzania is the clearest 2025 case of the election blackout, which Access Now recorded 12 times across 8 countries that year; a smaller category than conflict shutdowns, but the one that most directly attacks the verification of a result.", "srcTitle": "Tanzania: UN experts condemn post-election lethal crackdown and digital blackout, UN Office of the High Commissioner for Human Rights", "srcUrl": "https://www.ohchr.org/en/press-releases/2025/12/tanzania-un-experts-condemn-post-election-lethal-crackdown-and-digital", "key": false, "sum": "A complete national internet shutdown ran from 29 October to 3 November 2025, covering election day and its immediate aftermath."}, {"year": "29 September 2025", "place": "Afghanistan", "h": "The Taliban cut Afghanistan's fibre-optic network nationwide", "body": "The stated justification was preventing immoralities and stopping misuse of the internet, following attempts to filter fibre-optic traffic for the same purpose. The shutdown disrupted humanitarian aid delivery, healthcare, business and the online education used by girls barred from schooling beyond primary level.", "why": "This was a shutdown imposed for morality rather than security or protest; an ideological rationale that removes the usual implicit promise that connectivity returns once the crisis passes.", "srcTitle": "Afghanistan: Taliban de facto authorities must immediately restore internet access, Amnesty International", "srcUrl": "https://www.amnesty.org/en/latest/news/2025/09/afghanistan-taliban-de-facto-authorities-must-immediately-restore-internet-access/", "key": false, "sum": "On Monday 29 September 2025 the Taliban authorities imposed a nationwide telecommunications blackout affecting both mobile and fibre-optic services; NetBlocks measured activity at less than 1 percent of normal levels."}, {"year": "2025", "place": "Global (majority Gaza)", "h": "A record 129 press members are killed in a single year", "body": "Israel was responsible for 86 of them, roughly two in three global press deaths, and more than 60 percent of those 86 were Palestinians reporting from Gaza. CPJ stresses heavy caveats: investigation in Gaza is constrained by a foreign press ban, destroyed infrastructure and displacement, and it states that the true number of Palestinian journalists deliberately targeted \"may never be known.\" CPJ opened a review of its own documentation of the war in June 2026.", "why": "When the only reporters present are local and are being killed at record rates, the information control is achieved without any censorship instrument at all; which is the hardest form for international law to reach.", "srcTitle": "Record 129 press members killed in 2025; Israel responsible for 2 of 3 of deaths, Committee to Protect Journalists", "srcUrl": "https://cpj.org/special-reports/record-129-press-members-killed-in-2025-israel-responsible-for-2-of-3-of-deaths/", "key": true, "sum": "CPJ documented 129 journalists and media workers killed in 2025; the highest in more than three decades of record-keeping and the second consecutive record year."}, {"year": "8 January 2026 – ongoing", "place": "Iran", "h": "Iran runs the longest national internet blackout ever measured", "body": "A 98.5 percent drop in announced IPv6 address space removed much of Iran from global routing, local news agency sites became unreachable, and VPN access has been erratic throughout; a partial restoration from around 28 January brought traffic back to 50–60 percent of normal but introduced whitelisting that gives broader access only to vetted users. Casualty figures are unverifiable and contested, CPJ cited the Human Rights Activists News Agency in January reporting more than 18,000 detained and over 2,400 killed, and has itself said it has been unable to verify information about journalists inside Iran since the shutdown began.", "why": "A year-scale blackout in a country of 90 million establishes that a state can accept near-permanent disconnection as a governing cost, which is the outer limit of the technique and the hardest case for every legal remedy built since 2016.", "srcTitle": "Shutdown – Iran, Internet Society Pulse", "srcUrl": "https://pulse.internetsociety.org/en/shutdowns/blackout-in-iran/", "key": true, "sum": "Iran's blackout began at 16:30 UTC on 8 January 2026 amid nationwide protests over the economic crisis, and Internet Society Pulse records it as still running after more than 248 days."}], "n": 7}];
