window.FI_STATS=[{"v": "313", "k": "Internet shutdowns recorded in 2025", "d": "Across 52 countries, the worst year since the count began", "src": "https://www.accessnow.org/wp-content/uploads/2026/03/KeepItOn-Internet-Shutdowns-2025-Annual-Report.pdf", "by": "Access Now, #KeepItOn"}, {"v": "330", "k": "Journalists in prison on 1 December 2025", "d": "A fifth straight year above 300; China, Myanmar and Israel jailed the most", "src": "https://cpj.org/special-reports/2025-journalist-jailings-remain-stubbornly-high-harsh-prison-conditions-pervasive/", "by": "Committee to Protect Journalists"}, {"v": "57 of 72", "k": "Countries where people were arrested for a post", "d": "A record high, in the fifteenth consecutive year of global decline", "src": "https://freedomhouse.org/report/freedom-net/2025/uncertain-future-global-internet", "by": "Freedom House, Freedom on the Net 2025"}];
